 document.body.classList.toggle('touch-layout',mobile);
 document.body.classList.toggle('mobile-rotated',size.rotated);
 document.body.classList.toggle('mobile-compact',mobile&&size.height<=340);
 document.body.classList.toggle('mobile-narrow',mobile&&size.width<=740);
 viewport.style.width=size.width+'px';viewport.style.height=size.height+'px';
 viewport.style.setProperty('--game-width',size.width+'px');viewport.style.setProperty('--game-height',size.height+'px');
