function resetAKRecoil(){recoilShot=0;recoilLastShot=-Infinity;recoilYaw=0;recoilPitch=0;lastRecoilYaw=0;lastRecoilPitch=0;updateCrosshair();}
function startFiring(){if(!fire)resetAKRecoil();fire=true;shoot();}
