function reloadGun(){if(state!=='playing'||activeWeapon!=='ak'||weaponSwitch||reload>0||ammo===30||reserve<=0)return;reload=1.65;fire=false;resetAKRecoil();tone(320,.08,'square',.025,-150);showNotice('更换弹匣',1.65);}
