  weaponSwitch.elapsed=Math.min(weaponSwitch.duration,weaponSwitch.elapsed+dt);
  if(!weaponSwitch.swapped&&weaponSwitch.elapsed>=WEAPON_STOW_DURATION){
   previousWeapon=weaponSwitch.from;activeWeapon=weaponSwitch.to;weaponSwitch.swapped=true;
   tone(activeWeapon==='knife'?790:330,.09,'triangle',.025,activeWeapon==='knife'?-480:-160);
  }
