 burst(target.x,target.y,target.z,headshot?HEADSHOT_COLOR:palettes.lime,18);
 if(dog||kills%3===0)pickups.push({x:target.x,y:.45,z:target.z,phase:0,health:dog?40:25,ammo:dog?45:30,kind:dog?'dog':'milk'});
