function damage(n){player.hp=Math.max(0,player.hp-n);damageFlash=.55;tone(65,.2,'triangle',.075,-20);if(player.hp<=0)end(false);}
function bleedRemaining(){return player?Math.max(0,player.bleedUntil-elapsed):0;}
