  const sy=Math.sin(player.yaw),cy=Math.cos(player.yaw),sp=Math.sin(player.pitch),cp=Math.cos(player.pitch);
  const yaw=player.yaw+recoilYaw,pitch=clamp(player.pitch+recoilPitch,-Math.PI/2+.001,Math.PI/2-.001);
