 hat:[.075,.066,.080],hatLight:[.112,.095,.121],band:[.185,.105,.213],
 brow:[.165,.134,.111],eye:[.76,.72,.60],iris:[.38,.47,.265],pupil:[.092,.075,.093],
 green:[.30,.59,.155],greenLight:[.48,.79,.26],shoe:[.205,.18,.165]
